"""Plain-language summaries of one panel's results, generated by a local Ollama model.

Which results are high or low is decided in Python (status.py), from the report's
own flags, reference ranges and answers, and the panel's indices are computed in
analysis.py, so the model only explains results — it never has to read values,
judge ranges or do arithmetic itself.
"""

import os

import ollama

from status import result_status

OLLAMA_MODEL = os.environ.get("OLLAMA_MODEL", "qwen2.5vl:7b")

SYSTEM_PROMPT = (
    "You explain blood test results to a patient in plain, calm language. "
    "Only use the values and statuses given. Do not diagnose and do not recommend treatments."
)

# Small local models follow a fill-in-the-blanks skeleton in the user message
# far more reliably than format rules in the system prompt.
INSTRUCTIONS = (
    "Write the summary in exactly this format:\n\n"
    "<one sentence on what this panel checks and the overall picture>\n\n"
    "Results outside the normal range:\n"
    "- <test> (<value>, <high/low/abnormal>): <what the test measures>. "
    "<what a high or low value commonly relates to>.\n"
    "<one bullet like this for EVERY out-of-range result above, or the word None>\n\n"
    "Normal results: <one sentence on which tests were normal>\n\n"
    "<if indices are listed above: one sentence per index on what it describes>\n\n"
    "Please review these results with your doctor."
)

llm = ollama.Client()


def _describe(result):
    name = result.get("canonical") or result.get("test")
    value = " ".join(filter(None, [result.get("value_text"), result.get("unit")]))
    ref = f" (reference {result['reference_range']})" if result.get("reference_range") else ""
    return f"- {name}: {value}{ref} — {result_status(result)}"


def _describe_patient(patient):
    """"41-year-old male", or None if neither is known."""
    age, sex = (patient or {}).get("age"), (patient or {}).get("sex")
    if age is None and sex is None:
        return None
    return " ".join(filter(None, [f"{age:g}-year-old" if age is not None else None, sex or "patient"]))


def format_panel(analysis, results, patient=None):
    """The prompt for one panel: its out-of-range results in full first (so the
    model can't skip them), then normal and unrated ones, untested ones, indices
    and model results."""
    def names(status):
        return ", ".join(r.get("canonical") or r.get("test") for r in results if result_status(r) == status)

    abnormal = [_describe(r) for r in results if result_status(r) not in ("normal", "unknown")]
    indices = [f"- {i['name']}: {i['value']} ({i['note']})" for i in analysis["indices"]]
    indices += [f"- {m['name']}: {m['value']:g}{' ' + m['unit'] if m.get('unit') else ''} ({m['interpretation']})"
                for m in analysis.get("models", []) if m.get("value") is not None]
    who = _describe_patient(patient)
    return (
        f"Panel: {analysis['name']}\n"
        + (f"Patient: {who}\n" if who else "")
        + "\n"
        + f"Out-of-range results ({len(abnormal)}):\n" + ("\n".join(abnormal) or "None")
        + "\n\nNormal results: " + (names("normal") or "None")
        + "\n\nResults with no reference range (do not call these normal or abnormal): "
        + (names("unknown") or "None")
        + "\n\nTests in this panel that were not done: " + (", ".join(analysis["inputs"]["missing"]) or "None")
        + ("\n\nCalculated indices (already computed; do not recalculate):\n" + "\n".join(indices) if indices else "")
        + "\n\n" + INSTRUCTIONS
    )


def stream_panel_summary(analysis, results, patient=None):
    """Yield one panel's summary text in chunks as the model generates it.

    `results` are the panel's own results. The first chunk is requested eagerly
    so connection/model errors raise here, before the caller starts a streaming
    response.
    """
    stream = llm.chat(
        model=OLLAMA_MODEL,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": format_panel(analysis, results, patient)},
        ],
        stream=True,
        keep_alive="30m",
        options={"temperature": 0.2, "num_ctx": 4096, "num_predict": 450},
    )
    first = next(stream).message.content

    def chunks():
        yield first
        for part in stream:
            yield part.message.content

    return chunks()
